<div class="mvu-status-card">
    <div class="card-body" id="render-root">
        <div class="loading-state">正在加载状态数据...</div>
    </div>
</div>

<script type="module">
async function init() {
    await waitGlobalInitialized('Mvu');
    const rootDom = document.getElementById('render-root');

    function refreshStatus() {
        const allVars = getAllVariables();
        const sourceData = _.get(allVars, "stat_data", {});
        let htmlStr = '';

        // 递归渲染逻辑 完全保留 零改动
        function renderTree(obj, level = 0) {
            const indentClass = `indent-${Math.min(level, 4)}`;
            let itemsHtml = '';

            for (const [key, value] of Object.entries(obj)) {
                // 过滤私有变量 完全保留
                if (key.startsWith('_') || key.startsWith('$')) continue;

                // 对象嵌套 生成子分类标题 递归渲染
                if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
                    if (itemsHtml) {
                        htmlStr += `<div class="stat-grid ${indentClass}">${itemsHtml}</div>`;
                        itemsHtml = '';
                    }
                    if (level > 0) {
                        htmlStr += `<div class="category-title ${indentClass}">${key}</div>`;
                    }
                    renderTree(value, level + 1);
                    continue;
                }

                // 普通属性 加入当前层级网格
                itemsHtml += `<div class="stat-item">`;
                itemsHtml += `<span class="stat-label">${key}</span>`;
                itemsHtml += `<span class="stat-value">`;

                if (typeof value === 'number') {
                    itemsHtml += `<span class="value-number">${value}</span>`;
                } else if (typeof value === 'boolean') {
                    itemsHtml += value 
                        ? `<span class="value-true">✓</span>`
                        : `<span class="value-false">✕</span>`;
                } else {
                    itemsHtml += `<span class="value-text">${value}</span>`;
                }

                itemsHtml += `</span></div>`;
            }

            if (itemsHtml) {
                htmlStr += `<div class="stat-grid ${indentClass}">${itemsHtml}</div>`;
            }
        }

        renderTree(sourceData, 0);
        rootDom.innerHTML = htmlStr;
        rootDom.classList.add('flash-update');
        setTimeout(() => rootDom.classList.remove('flash-update'), 300);
    }

    // 初始化 + 变量更新监听 完全保留
    refreshStatus();
    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, refreshStatus);
}

$(errorCatched(init));
</script>

</body>
</html>
